KG42.register("rules-4c9a76c09fa3cdebb1827f2e",{"id":"45-heat_pump_flexibility::v141-c-R007","paper":"45-heat_pump_flexibility","record":{"rule_id":"v141-c-R007","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"Demand bids are submitted before the physical energy exchange at delivery. Scope: Demand submission in the study's pre-delivery LEM workflow. Supply offers are submitted before the physical energy exchange at delivery. Scope: Supply submission in the study's pre-delivery LEM workflow. Local market clearing occurs before the physical energy exchange at the delivery time step. Scope: Market clearing in the rolling pre-delivery workflow of the study LEM. Buyers may purchase energy when their bid price meets or exceeds the uniform local market price. Scope: Buyer-side trading permission in the uniform-price, two-sided LEM auction. Condition: The buyer's bid price is greater than or equal to the uniform local market price. Sellers may sell energy when their offered price does not exceed the uniform local market price. Scope: Seller-side trading permission in the uniform-price, two-sided LEM auction. Condition: The seller's offered price is less than or equal to the uniform local market price. The LEM permits electricity trading up to 24 h in advance of delivery. Scope: Future-market trading in the study LEM, including day-ahead, intraday and near real-time operation.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","clearing.local","execution.energy_trade","pricing.local"],"E":[{"edge_id":"v141-c-R007-E001","source":"bidding.demand","target":"execution.energy_trade","type":"precedes","constraint_ids":["v141-c-R007-C001"],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e06"]},{"edge_id":"v141-c-R007-E002","source":"bidding.supply","target":"execution.energy_trade","type":"precedes","constraint_ids":["v141-c-R007-C002"],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e06"]},{"edge_id":"v141-c-R007-E003","source":"clearing.local","target":"execution.energy_trade","type":"precedes","constraint_ids":["v141-c-R007-C003"],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e06"]},{"edge_id":"v141-c-R007-E004","source":"execution.energy_trade","target":"pricing.local","type":"conditional_on","constraint_ids":["v141-c-R007-C004","v141-c-R007-C005"],"evidence_ids":["v141-b-g01-e12"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Buyer-side trading permission in the uniform-price, two-sided LEM auction. | Demand submission in the study's pre-delivery LEM workflow. | Future-market trading in the study LEM, including day-ahead, intraday and near real-time operation. | Market clearing in the rolling pre-delivery workflow of the study LEM. | Seller-side trading permission in the uniform-price, two-sided LEM auction. | Supply submission in the study's pre-delivery LEM workflow.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e06","v141-b-g01-e07","v141-b-g01-e12"]},"x":[{"variable_id":"p_bid_i","symbol":"p^{bid}_i","meaning":"Bid price submitted by buyer i in the uniform-price local auction, used in the buyer-side trading permission condition.","kind":"operational","domain":"Buyer bid-price values in the modeled LEM auction; the cited evidence does not state numeric bounds.","unit":null,"indices":["i"],"evidence_ids":["v141-b-g01-e12"]},{"variable_id":"p_offer_j","symbol":"p^{offer}_j","meaning":"Offer price submitted by seller j in the uniform-price local auction, used in the seller-side trading permission condition.","kind":"operational","domain":"Seller offer-price values in the modeled LEM auction; the cited evidence does not state numeric bounds.","unit":null,"indices":["j"],"evidence_ids":["v141-b-g01-e12"]}],"theta":[{"parameter_id":"p_market","symbol":"p^{market}","meaning":"Uniform local market price at which all accepted bids pay or receive the same price, used as the threshold in buyer and seller trading permissions.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e12"]}],"phi":[{"constraint_id":"v141-c-R007-C001","kind":"procedural","role":"core","statement":"Demand bids are submitted before the physical energy exchange at delivery. Scope: Demand submission in the study's pre-delivery LEM workflow.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e06"]},{"constraint_id":"v141-c-R007-C002","kind":"procedural","role":"core","statement":"Supply offers are submitted before the physical energy exchange at delivery. Scope: Supply submission in the study's pre-delivery LEM workflow.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e06"]},{"constraint_id":"v141-c-R007-C003","kind":"procedural","role":"core","statement":"Local market clearing occurs before the physical energy exchange at the delivery time step. Scope: Market clearing in the rolling pre-delivery workflow of the study LEM.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e06"]},{"constraint_id":"v141-c-R007-C004","kind":"logical","role":"core","statement":"Buyers may purchase energy when their bid price meets or exceeds the uniform local market price. Scope: Buyer-side trading permission in the uniform-price, two-sided LEM auction. Condition: The buyer's bid price is greater than or equal to the uniform local market price.","expression":"\\forall i,\\; p^{bid}_i \\ge p^{market} \\Rightarrow \\mathrm{buy}_i","formalization_origin":"source","template_id":null,"members":["execution.energy_trade","pricing.local"],"variable_refs":["p_bid_i"],"parameter_refs":["p_market"],"evidence_ids":["v141-b-g01-e12"]},{"constraint_id":"v141-c-R007-C005","kind":"logical","role":"core","statement":"Sellers may sell energy when their offered price does not exceed the uniform local market price. Scope: Seller-side trading permission in the uniform-price, two-sided LEM auction. Condition: The seller's offered price is less than or equal to the uniform local market price.","expression":"\\forall j,\\; p^{offer}_j \\le p^{market} \\Rightarrow \\mathrm{sell}_j","formalization_origin":"source","template_id":null,"members":["execution.energy_trade","pricing.local"],"variable_refs":["p_offer_j"],"parameter_refs":["p_market"],"evidence_ids":["v141-b-g01-e12"]},{"constraint_id":"v141-c-R007-C006","kind":"procedural","role":"core","statement":"The LEM permits electricity trading up to 24 h in advance of delivery. Scope: Future-market trading in the study LEM, including day-ahead, intraday and near real-time operation.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e07"]}],"pi":[{"evidence_id":"v141-b-g01-e05","location":{"location_id":"src-115be449fd-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":null,"section":null,"anchor_text":"3. submitting bids: send their bids and offers to the LEM based on to the optimal schedules prior to","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"In general, prosumers must complete the following steps to achieve energy exchange in the LEM:\n1. forecasts: make forecasts about weather, demands, and electricity prices;\n2. model-predictive control: use the model-predictive control (MPC) to generate the optimal schedules for their flexible loads such HPs, EVs, and batteries;\n3. submitting bids: send their bids and offers to the LEM based on the optimal schedules prior to the delivery time\n4. market clearing: match the demand and supply and clear the market;\n5. receiving results: receives the market clearing results for the delivery time after the market clearing;\n6. real-time control: use real-time controller to adjust the operating states of the flexible loads at the delivery time according to the electricity procured from the LEM;\n7. settlement: settle the consumption or generation soon after the electricity has been delivered\n\nThe steps 1 to 5 should be repeated for every rolling horizon prior to the delivery time step. Prosumers should check the clearing results from the previous rolling horizon to ensure that the procured electricity is sufficient for their energy demand at the time step of delivery."},{"evidence_id":"v141-b-g01-e06","location":{"location_id":"src-115be449fd-p04-c1r2__v141-a-M01-settlement","page":4,"printed_page":null,"section":null,"anchor_text":"Fig. 2. Timeline of the trading process in the LEM. to su Otherwise, they should continue bidding at","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"unknown"},"source_text":"Otherwise, they should continue bidding at later time steps until they have obtained enough electricity. During the delivery time step, the physical flow of energy takes place, and real-time control is activated to ensure precise consumption. Finally, the costs are settled based on the metering data that reflects the real consumption. The whole process is illustrated in Fig. 2."},{"evidence_id":"v141-b-g01-e07","location":{"location_id":"src-115be449fd-p04-c1r3__v141-a-M01-clearing","page":4,"printed_page":null,"section":null,"anchor_text":"Limited by the scope, the description of other parts of lemlab is omitted Th in this work. However, ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The LEM uses a future market design, which is the most common market design found in the literature [29]. Therefore, the LEM undergoes clearing every 15 min, with a 24 h trading horizon, allowing prosumers to trade electricity up to 24 h in advance. This allows the LEM to function as a day-ahead, intraday, or near real-time market. If prosumers are unable to fulfill their energy demand in one round of market clearing, they can continue submitting their bids in subsequent trading cycles. During settlement, any energy imbalances resulting from a deviation from the traded position lead to additional balancing costs."},{"evidence_id":"v141-b-g01-e12","location":{"location_id":"src-115be449fd-p04-c2r2__v141-a-M01-pricing","page":4,"printed_page":null,"section":null,"anchor_text":"Fig. 3. Visualization of a double-sided auction. The two-sided auction allows for consumption and pr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Additionally, the auction operates as a uniform price auction, with all accepted bids paying or receiving the same market price. All buyers who bid above or equal to this price can buy, while all sellers who sell below or equal to this price can sell."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-activation","v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-matching","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-settlement"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e05","quote":"3. submitting bids: send their bids and offers to the LEM based on the optimal schedules prior to the delivery time"},{"evidence_id":"v141-b-g01-e06","quote":"During the delivery time step, the physical flow of energy takes place"}],[{"evidence_id":"v141-b-g01-e05","quote":"3. submitting bids: send their bids and offers to the LEM based on the optimal schedules prior to the delivery time"},{"evidence_id":"v141-b-g01-e06","quote":"During the delivery time step, the physical flow of energy takes place"}],[{"evidence_id":"v141-b-g01-e05","quote":"4. market clearing: match the demand and supply and clear the market;"},{"evidence_id":"v141-b-g01-e05","quote":"The steps 1 to 5 should be repeated for every rolling horizon prior to the delivery time step."},{"evidence_id":"v141-b-g01-e06","quote":"During the delivery time step, the physical flow of energy takes place"}],[{"evidence_id":"v141-b-g01-e12","quote":"Additionally, the auction operates as a uniform price auction, with all accepted bids paying or receiving the same market price. All buyers who bid above or equal to this price can buy, while all sellers who sell below or equal to this price can sell."}],[{"evidence_id":"v141-b-g01-e12","quote":"Additionally, the auction operates as a uniform price auction, with all accepted bids paying or receiving the same market price. All buyers who bid above or equal to this price can buy, while all sellers who sell below or equal to this price can sell."}],[{"evidence_id":"v141-b-g01-e07","quote":"with a 24 h trading horizon, allowing prosumers to trade electricity up to 24 h in advance. This allows the LEM to function as a day-ahead, intraday, or near real-time market."}]],"C2_formalization":{"graph_sha256":"64695e1f0871b73037a0a02c02dd52937711c19e219a2f64fe354014503b12b2","applicability":"formalized","reason":"The unreviewed candidate evidence v141-b-g01-e12 directly states the uniform-price buyer and seller threshold permissions, which can be represented as logical price inequalities. The remaining timing/precedence statements are procedural and are retained as not_formalized because the cited text supplies no symbolic timestamps or ordering formula. This does not assert that B transcription or downstream science has passed independent source review.","bindings":[{"object_id":"p_bid_i","node_ids":["bidding.demand"],"edge_ids":["v141-c-R007-E001"],"rationale":"The buyer bid price is a demand-bidding attribute; edge E001 carries demand bidding into execution.energy_trade, where the threshold permission applies."},{"object_id":"p_offer_j","node_ids":["bidding.supply"],"edge_ids":["v141-c-R007-E002"],"rationale":"The seller offer price is a supply-bidding attribute; edge E002 carries supply bidding into execution.energy_trade, where the threshold permission applies."},{"object_id":"p_market","node_ids":["pricing.local"],"edge_ids":["v141-c-R007-E004"],"rationale":"The uniform local market price belongs to pricing.local; edge E004 makes execution.energy_trade conditional on pricing.local."},{"object_id":"v141-c-R007-C004","node_ids":["execution.energy_trade","pricing.local","bidding.demand"],"edge_ids":["v141-c-R007-E004","v141-c-R007-E001"],"rationale":"The buyer-side permission compares the demand bid price with the uniform local market price. E004 is the execution-to-pricing conditional edge; E001 links the demand bid entering the condition."},{"object_id":"v141-c-R007-C005","node_ids":["execution.energy_trade","pricing.local","bidding.supply"],"edge_ids":["v141-c-R007-E004","v141-c-R007-E002"],"rationale":"The seller-side permission compares the supply offer price with the uniform local market price. E004 is the execution-to-pricing conditional edge; E002 links the supply offer entering the condition."}],"revision_requests":[]}},"quarantined_references":[]}});
